with feeders as (
    select
        md5(upper('LNK_POLICY_PARTY|' || (LNK_POLICY_PARTY_BK__POLICY_NO_EMP_CODE))) as LNK_POLICY_PARTY_HK
        , DISCLAIMER_INDICATOR as DISCLAIMER_ACCEPTED_INDICATOR
        , 'BJAZ_HAT_POL_EMP_MAP' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_pol_emp_map') }}
    where (LNK(HUB_POLICY = nullif(trim(POLICY_NO),''), HUB_PARTY = nullif('EMP:' || coalesce(nullif(trim(POLICY_NO),''),'') || '#' || coalesce(nullif(trim(EMP_CODE),''),''), 'EMP:#'))) is not null
),

resolved as (
    select
        LNK_POLICY_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then DISCLAIMER_ACCEPTED_INDICATOR end) as DISCLAIMER_ACCEPTED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by LNK_POLICY_PARTY_HK
),

hashed as (
    select
        *,
        case when DISCLAIMER_ACCEPTED_INDICATOR is not null
                     then md5(upper(coalesce(cast(DISCLAIMER_ACCEPTED_INDICATOR as varchar), '')))
                end as SAT_LNK_POLICY_PARTY_ROLE_HASHDIFF
    from resolved
)

